    let printed = format!("{start:?} {header:?} {:?}", start.report("2026-10-30T00:00:00Z"));
    for leak in ["Basic ", "YWJj", "Authorization="] {
        assert!(!printed.contains(leak), "{leak:?} leaked into: {printed}");
    }
    assert!(printed.contains("<redacted>"), "{printed}");
