            let seconds = card.waste.seconds(cause);
            if seconds > 0 {
                add(
                    "observatory.waste_seconds",
                    vec![
                        mission_label(),
                        (Label::Milestone, milestone.clone()),
                        (Label::Cause, waste_label(cause).to_owned()),
                    ],
                    seconds as f64,
