    let real = || events.iter().filter(|event| !event.kind.is_panel_only());
    let seconds = |from: Timestamp, to: Timestamp| (to.0 - from.0).as_seconds_f64().max(0.0);
    if let (Some(first), Some(done)) = (
        real().map(|event| event.at).min(),
